import type {Velocity} from './main';
export type W<T> = Write<T>;
export type R<T> = Read<T>;
export type Modes<T> = [W<T>,R<Velocity>];
export type Q<T extends unknown[]> = Query<T>;

import type {Q,Modes} from './aliases';
// complete architecture Query source: emoji 😀
@component
export class Position { x: f32 = 0; y: f32 = 0; }
@component
export class Velocity { x: f32 = 0; y: f32 = 0; }
@system
export function integrate(q: Q<Modes<Position>>, dt: f32): void {
 for(const [p,v] of q){
  p.x += v.x * dt;
  p.y += v.y * dt;
 }
}

